const body = $json.body || $json;
const entry = body && body.entry && body.entry[0];
if (!entry) return [];

const messaging = entry.messaging && entry.messaging[0];
const change = entry.changes && entry.changes[0];

// ── Messenger direct message (incoming or echo) ──
if (messaging) {
  // Card button tap. The payload is ORDER:<productId>, so it becomes a marker
  // the AI understands; the title is kept as the visible inbox text.
  const postback = messaging.postback;
  if (postback && typeof postback.payload === 'string' && postback.payload.indexOf('ORDER:') === 0) {
    const psid = messaging.sender && messaging.sender.id;
    const page = entry.id || (messaging.recipient && messaging.recipient.id);
    if (!psid) return [];
    return [{
      json: {
        pageId: page,
        senderId: psid,
        isComment: false,
        isEcho: false,
        commentId: '',
        sessionId: 'fb_' + psid,
        userMessage: '[ORDER_CARD:' + postback.payload.slice(6) + '] ' + (postback.title || ''),
        mediaType: 'text',
        mediaUrl: ''
      }
    }];
  }

  // Any other button tap still reaches the AI instead of being silently dropped.
  if (postback) {
    const fbPsid = messaging.sender && messaging.sender.id;
    const fbPage = entry.id || (messaging.recipient && messaging.recipient.id);
    if (!fbPsid) return [];
    return [{
      json: {
        pageId: fbPage,
        senderId: fbPsid,
        isComment: false,
        isEcho: false,
        commentId: '',
        sessionId: 'fb_' + fbPsid,
        userMessage: postback.title || String(postback.payload || ''),
        mediaType: 'text',
        mediaUrl: ''
      }
    }];
  }

  const msg = messaging.message || {};
  const isEcho = !!(msg && msg.is_echo);

  // Meta ID Swap Fix:
  // - Echo message (sent by merchant on Meta Business Suite/Facebook):
  //   sender = PAGE_ID, recipient = CUSTOMER_PSID
  // - Incoming message (sent by customer):
  //   sender = CUSTOMER_PSID, recipient = PAGE_ID
  const customerPsid = isEcho
    ? (messaging.recipient && messaging.recipient.id)
    : (messaging.sender && messaging.sender.id);

  const pageId = entry.id || (isEcho ? (messaging.sender && messaging.sender.id) : (messaging.recipient && messaging.recipient.id));

  if (!customerPsid) return [];

  let userMessage = msg.text || '';
  let mediaType = 'text';
  let mediaUrl = '';
  const att = msg.attachments && msg.attachments[0];
  if (att && att.type === 'image') {
    mediaType = 'image';
    mediaUrl = (att.payload && att.payload.url) || '';
  } else if (att && att.type === 'audio') {
    mediaType = 'audio';
    mediaUrl = (att.payload && att.payload.url) || '';
  } else if (att) {
    // A video, sticker or file is a real message this channel cannot read.
    // Saying so keeps the conversation alive; returning nothing — what an empty
    // text used to do — dropped it silently and looked like the bot was broken.
    userMessage = userMessage ? userMessage + '\n' + '[The customer sent an attachment this channel cannot process (for example a video, a sticker or a file). Politely ask them to describe it in text, or send a photo or a voice note instead.]' : '[The customer sent an attachment this channel cannot process (for example a video, a sticker or a file). Politely ask them to describe it in text, or send a photo or a voice note instead.]';
  }

  if (!userMessage && mediaType === 'text') return [];

  const sessionId = 'fb_' + customerPsid;

  return [{
    json: {
      pageId,
      senderId: customerPsid,
      isComment: false,
      isEcho,
      commentId: '',
      sessionId,
      userMessage,
      mediaType,
      mediaUrl
    }
  }];
}

// ── Page feed comment ──
if (change && change.field === 'feed' && change.value && change.value.item === 'comment' && change.value.verb === 'add') {
  const v = change.value;
  const pageId = entry.id || '';
  const fromId = (v.from && v.from.id) || '';
  if (!fromId || fromId === pageId) return [];
  if (!v.message) return [];
  return [{
    json: {
      pageId,
      senderId: fromId,
      isComment: true,
      isEcho: false,
      commentId: v.comment_id || '',
      sessionId: 'fbc_' + (v.comment_id || fromId),
      userMessage: v.message,
      mediaType: 'text',
      mediaUrl: ''
    }
  }];
}

return [];

// ─────────────────────────────────────────────────────────────────────────────
// Build Brain Payload
// 1. Fetch Meta User Profile (name + profile_pic) for the sender.
// 2. Format profile data & create _upsert payload for PostgreSQL.
// 3. Return enriched payload for Execute Core AI Brain.
// ─────────────────────────────────────────────────────────────────────────────

const fbPayload   = $('Normalize FB Payload').item.json;
const integration = $('Fetch Integration Secrets').item.json;

const chatbotId   = integration.chatbotId;
const pageToken   = (integration.pageAccessToken || '').trim();
const sessionId   = fbPayload.sessionId;
const senderId    = (fbPayload.senderId || '').trim();
const isComment   = fbPayload.isComment;
const userMessage = fbPayload.userMessage;
const mediaType   = fbPayload.mediaType;
const mediaUrl    = fbPayload.mediaUrl;

let userName     = 'Facebook User';
let profilePhoto = '';

// ── Step 1: Fetch Meta user profile (Messenger Direct Messages only) ─────────
if (!isComment && senderId && pageToken) {
  const profileUrl = `https://graph.facebook.com/v20.0/${senderId}?fields=first_name,last_name,profile_pic&access_token=${pageToken}`;

  try {
    let profile = null;

    // 1. Try n8n's official httpRequest helper (bypasses sandbox limitations)
    if (typeof this !== 'undefined' && this.helpers && typeof this.helpers.httpRequest === 'function') {
      profile = await this.helpers.httpRequest({
        method: 'GET',
        url: profileUrl,
        json: true
      });
    } else if (typeof fetch === 'function') {
      // 2. Fallback to native fetch
      const res = await fetch(profileUrl);
      if (res.ok) {
        profile = await res.json();
      }
    }

    if (profile) {
      const firstName = (profile.first_name || '').trim();
      const lastName  = (profile.last_name  || '').trim();
      const fullName  = [firstName, lastName].filter(Boolean).join(' ');
      if (fullName) userName = fullName;
      if (profile.profile_pic) profilePhoto = profile.profile_pic;
    }
  } catch (err) {
    console.error('[Build Brain Payload] Profile fetch failed:', err.message || err);
  }
}

// ── Step 2: Prepare Upsert Data ──────────────────────────────────────────────
const upsertPayload = {
  chatbotId,
  sessionId,
  guestName: userName,
  profilePhoto: profilePhoto || ''
};

// ── Step 3: Return enriched payload ──────────────────────────────────────────
return [{
  json: {
    chatbotId,
    sessionId,
    customerName: userName,
    profilePhoto: profilePhoto || null,
    userMessage,
    mediaType,
    mediaUrl,
    // Meta serves Facebook/Instagram media from public URLs, so no header is needed.
    mediaAuthHeader: '',
    platform: 'facebook',
    _upsert: upsertPayload
  }
}];

// Messenger generic-template carousel: at most 10 cards, up to two buttons,
// title and subtitle are capped at 80 characters by Meta. Products the agent
// named but that have no public HTTPS image are dropped instead of failing the
// whole request. A product with a public post URL gets a second button that
// opens the original post, where every photo is visible - the template itself
// can show only one image per card.
const cards = $('Execute Core AI Brain').item.json.productCards || [];

const elements = cards.slice(0, 10).map((card) => {
  const currency = String(card.currency || 'BDT');
  const amount = Number(card.price);
  const price = Number.isFinite(amount)
    ? (currency === 'BDT' ? '৳' : currency + ' ') + amount.toLocaleString('en-US')
    : String(card.price || '');

  // The second button is the original post, where every photo of the product
  // lives. web_url needs an absolute HTTPS URL, so a missing or relative
  // postUrl drops only the button - never the whole card.
  const postUrl = String(card.postUrl || '');
  const buttons = [
    {
      type: 'postback',
      title: '🛒 Order',
      payload: 'ORDER:' + card.productId
    }
  ];
  if (/^https:\/\//i.test(postUrl)) {
    buttons.push({ type: 'web_url', title: '🖼️ Details', url: postUrl });
  }

  return {
    title: String(card.name || '').slice(0, 80),
    subtitle: price.slice(0, 80),
    image_url: String(card.imageUrl || ''),
    buttons
  };
}).filter((element) => /^https:\/\//i.test(element.image_url));

return [{
  json: {
    carouselBody: {
      attachment: {
        type: 'template',
        payload: {
          template_type: 'generic',
          elements
        }
      }
    }
  }
}];
